static const size_t HEBREW_DATES_COUNT = sizeof(HEBREW_DATES) / sizeof(HEBREW_DATES[0]);

// Returns the Hebrew date for a Gregorian y/m/d, or nullptr if outside the
// generated range.
inline const char* hebrewDateForGregorian(int year, int month, int day) {
  uint32_t key = (uint32_t)year * 10000u + (uint32_t)month * 100u + (uint32_t)day;
  int lo = 0, hi = (int)HEBREW_DATES_COUNT - 1;
  while (lo <= hi) {
    int mid = (lo + hi) / 2;
    uint32_t g = HEBREW_DATES[mid].greg;
    if (g == key) return HEBREW_DATES[mid].hebrew;
    if (g < key)  lo = mid + 1;
    else          hi = mid - 1;
  }
  return nullptr;
}

// Convenience overload for a struct tm (tm_year since 1900, tm_mon 0..11).
inline const char* hebrewDateForTm(const struct tm& t) {
  return hebrewDateForGregorian(t.tm_year + 1900, t.tm_mon + 1, t.tm_mday);
}
